function draw({board,width,height,params}) {
  const P=VisualBook.palette, x=[0,1,2,3], y=x.map(t=>t*t), v=[1,1,1,params.v3];
  const g=x.map((t,i)=>2*t*v[i]);
  const f=board.axes('gradient-axes',{xDomain:[-0.4,3.4],yDomain:[-8,14],xLabel:'',yLabel:'',box:[54,170,width-26,height-68],grid:true});
  board.text('output-heading','输出 yᵢ = xᵢ²',20,21,{size:15,color:P.blue});
  board.text('seed-heading','反传种子 vᵢ',20,83,{size:15,color:P.orange});
  const subs=['₀','₁','₂','₃'];
  for(let i=0;i<4;i++){
    const xx=f.x(i), c=i===3?P.orange:P.blue;
    board.text('output-'+i,'y'+subs[i]+' = '+y[i],xx,49,{anchor:'middle',size:15,color:P.blue});
    board.text('seed-'+i,'v'+subs[i]+' = '+Number(v[i].toFixed(2)),xx,111,{anchor:'middle',size:15,color:i===3?P.orange:P.muted});
    board.line('stem-'+i,xx,f.y(0),xx,f.y(g[i]),c,8,0.75);
    board.circle('tip-'+i,xx,f.y(g[i]),4,c);
    board.text('g-'+i,String(Number(g[i].toFixed(2))),xx,f.y(g[i])+-10,{anchor:'middle',size:15,color:c});
  }
  board.text('gradient-heading','梯度 gᵢ',20,143,{size:15,color:P.ink});
  board.text('coordinate-heading','输入分量 i',width-26,height-8,{anchor:'end',size:15,color:P.muted});
  board.text('chain-rule','gᵢ = 2xᵢ vᵢ',width-26,139,{anchor:'end',size:15,color:P.ink});
  return {x,y,seeds:v,jacobian:x.map((t,i)=>x.map((_,j)=>i===j?2*t:0)),inputGradient:g,weightedObjective:y.reduce((a,t,i)=>a+t*v[i],0),convention:'固定原文输入；输出加权和的梯度 Jᵀv，不代表训练。'};
}

function draw({board,width,height,params}) {
  const P=VisualBook.palette, narrow=width<500, x=3, y=x*x, u=y, z=u*x, stopped=params.mode==='detach';
  const direct=u, indirect=stopped?0:2*x*x, total=direct+indirect;
  const nodes={x:[width*.14,196],y:[width*.38,100],u:[width*.66,100],z:[width*.86,196]};
  const bw=narrow?62:76, bh=54;
  function route(id,pts,color,dash){
    board.path(id,pts,{color,width:2,opacity:1});
    if(dash)board.mark(id+'-dash','path',{d:pts.map((p,i)=>(i?'L':'M')+p[0]+','+p[1]).join(' '),fill:'none',stroke:P.paper,'stroke-width':3,'stroke-dasharray':'4 5'});
    const a=pts[pts.length-2],b=pts[pts.length-1],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len;
    board.path(id+'-head',[[b[0]-ux*7-uy*3,b[1]-uy*7+ux*3],b,[b[0]-ux*7+uy*3,b[1]-uy*7-ux*3]],{color,width:2});
  }
  const [X,Y,U,Z]=['x','y','u','z'].map(k=>nodes[k]);
  route('forward-xy',[[X[0],X[1]-bh/2],[Y[0],Y[1]+bh/2]],P.blue);
  route('forward-yu',[[Y[0]+bw/2,Y[1]-5],[U[0]-bw/2,U[1]-5]],P.blue);
  route('forward-uz',[[U[0],U[1]+bh/2],[Z[0],Z[1]-bh/2]],P.blue);
  route('forward-xz',[[X[0]+bw/2,X[1]],[Z[0]-bw/2,Z[1]]],P.blue);
  route('reverse-direct',[[Z[0],Z[1]+bh/2],[Z[0],262],[X[0],262],[X[0],X[1]+bh/2]],P.orange);
  route('reverse-zu',[[Z[0]-8,Z[1]-bh/2],[U[0]-8,U[1]+bh/2]],P.orange);
  if(!stopped){
    route('reverse-uy',[[U[0]-bw/2,U[1]+7],[Y[0]+bw/2,Y[1]+7]],P.orange);
    route('reverse-yx',[[Y[0]-8,Y[1]+bh/2],[X[0]-8,X[1]-bh/2]],P.orange);
  } else {
    board.line('blocked-edge',U[0]-bw/2,U[1]+7,Y[0]+bw/2,Y[1]+7,P.faint,2);
  }
  board.text('mode-title',stopped?'u = detach(y)':'u = y',20,23,{size:16,color:P.ink});
  board.text('legend','蓝：前向值　橙：反向贡献',20,49,{size:15,color:P.muted});
  for(const [id,label,val] of [['x','x₃',x],['y','y₃',y],['u','u₃',u],['z','z₃',z]]){
    const [cx,cy]=nodes[id];
    board.rect('node-'+id,cx-bw/2,cy-bh/2,bw,bh,P.paper,{stroke:P.faint,rx:7});
    board.text('label-'+id,label,cx,cy-4,{anchor:'middle',size:15,color:P.ink});
    board.text('value-'+id,String(val),cx,cy+17,{anchor:'middle',size:16,color:P.blue});
  }
  board.text('cut-symbol',stopped?'×':'←',(Y[0]+U[0])/2,116,{anchor:'middle',size:21,color:P.orange});
  board.text('cut-label',stopped?'梯度到此停止':'梯度经过 y',(Y[0]+U[0])/2,148,{anchor:'middle',size:15,color:P.muted});
  board.text('square-operation','平方',width*.23,157,{anchor:'middle',size:15,color:P.muted});
  board.text('multiply-operation','相乘',width/2,221,{anchor:'middle',size:15,color:P.muted});
  board.text('same-forward','z₃ = 27，前向值相同',width/2,246,{anchor:'middle',size:15,color:P.blue});
  const ys=narrow?[313,347,387]:[315,315,315];
  const xs=narrow?[20,20,20]:[20,width*.36,width*.73];
  board.text('direct-value','直接路径  x₃² = '+direct,xs[0],ys[0],{size:16,color:P.orange});
  board.text('indirect-value','经 y 路径  '+(stopped?'0':'2x₃² = '+indirect),xs[1],ys[1],{size:16,color:P.orange});
  board.text('total-value','合计 g = '+total,xs[2],ys[2],{size:17,color:P.ink,weight:600});
  return {x,y,u,z,mode:params.mode,directContribution:direct,viaYContribution:indirect,inputGradient:total,forwardValuesIdentical:true,convention:'原文第3分量 x₃=3；detach只截断导数路径；比较两种计算图，无训练。'};
}
